<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import type { AiRequest, AiResult, AiSource } from '../domain/ai'
import type { KnowledgePoint, ResourceItem } from '../domain/types'
import MarkdownText from './MarkdownText.vue'
import Icon from './Icon.vue'
const props = defineProps<{ points: KnowledgePoint[]; resources: ResourceItem[]; busy: boolean; error: string; phase: string; detail: string; result: AiResult | null; partial: string; sessionId: string; configured: boolean }>()
const emit = defineEmits<{ start: [request: AiRequest]; cancel: []; reset: []; settings: []; locate: [id: string]; preview: [resource: ResourceItem] }>()
const question = ref(''); const action = ref<'search' | 'answer'>('search'); const supplement = ref(false); const selectedResources = ref<string[]>([])
const history = ref<{ question: string; result: AiResult }[]>([])
const lastQuestion = ref('')
const output = ref<Exclude<AiResult, { kind: 'extract' }> | null>(null)
watch(() => props.result, value => { if (value && value.kind !== 'extract') output.value = value })
const hits = computed(() => output.value?.kind === 'search' ? output.value.hits.map(hit => ({ ...hit, point: props.points.find(p => p.id === hit.pointId) })).filter(hit => hit.point) : [])
function submit() {
  if (!question.value.trim() || props.busy) return
  if (output.value && lastQuestion.value) history.value.push({ question: lastQuestion.value, result: JSON.parse(JSON.stringify(output.value)) })
  output.value = null
  lastQuestion.value = question.value.trim()
  emit('start', { action: action.value, text: question.value.trim(), resourceIds: selectedResources.value.filter(id => props.resources.some(r => r.id === id)), sessionId: props.sessionId || undefined, allowSupplement: supplement.value })
}
function reset() { emit('reset'); history.value = []; output.value = null; lastQuestion.value = ''; question.value = '' }
function sourceAvailable(source: AiSource) { if (source.pointId && !props.points.some(p => p.id === source.pointId)) return false; return source.resourceId ? props.resources.some(r => r.id === source.resourceId) : !!source.pointId }
function openSource(source: AiSource) { if (source.resourceId) { const resource = props.resources.find(r => r.id === source.resourceId); if (resource) emit('preview', resource) } else if (source.pointId) emit('locate', source.pointId) }
const textResources = computed(() => props.resources.filter(r => ['text', 'markdown'].includes(r.kind)))
</script>
<template><section class="ai-knowledge-panel" aria-label="AI 知识助手"><div class="ai-mode-row" role="group" aria-label="AI 操作"><button class="button compact-button" :class="{'button-primary':action==='search'}" @click="action='search'">查找知识</button><button class="button compact-button" :class="{'button-primary':action==='answer'}" @click="action='answer'">回答问题</button><button class="text-button ai-new-session" :disabled="busy" @click="reset">新会话</button></div><form @submit.prevent="submit"><label class="sr-only" for="ai-question">自然语言问题</label><textarea id="ai-question" v-model="question" class="field ai-question" aria-label="自然语言问题" data-testid="ai-question" placeholder="例如：进入 Docker 容器终端，但我忘了命令" rows="3" @keydown.ctrl.enter.prevent="submit" /><p class="ai-context-summary">发送范围：本次问题、必要对话及检索到的知识和资料信息。</p><details v-if="textResources.length" class="ai-text-context"><summary>允许读取的文本资料（{{selectedResources.length}}）</summary><label v-for="resource in textResources" :key="resource.id"><input v-model="selectedResources" type="checkbox" :value="resource.id" />{{resource.title}}</label></details><label v-if="action==='answer'" class="ai-check"><input v-model="supplement" type="checkbox" aria-label="允许 AI 补充通用知识" />允许补充通用知识，并单独标识</label><div class="ai-submit-row"><button v-if="busy" class="button" type="button" data-testid="ai-cancel" @click="emit('cancel')">取消</button><button v-else-if="!configured" class="button" type="button" @click="emit('settings')">配置 DeepSeek</button><button class="button button-primary" type="submit" :disabled="busy || !question.trim()" data-testid="ai-submit"><Icon name="search" :size="15" />{{action==='search'?'自动查找':'检索并回答'}}</button></div></form><p v-if="busy" role="status" class="ai-task-status"><span class="spinner small" />{{phase}}<small v-if="detail">{{detail}}</small></p><p v-else-if="phase === '已取消'" class="ai-help" role="status">已取消。问题仍保留，可再次提交。</p><div v-if="error" class="ai-error" role="alert" data-testid="ai-error">{{error}}<button class="text-button" @click="submit">重试</button></div><div v-if="history.length" class="ai-conversation-history"><details v-for="(turn,index) in history" :key="index"><summary>{{turn.question}}</summary><template v-if="turn.result.kind==='answer'"><section v-for="(block,i) in turn.result.blocks" :key="i" class="ai-answer-block"><p class="ai-basis">{{{personal:'已有知识依据',inference:'结构推断',supplement:'AI 补充'}[block.basis]}}</p><MarkdownText :text="block.markdown" /><div class="ai-source-list"><button v-for="source in turn.result.sources.filter(s=>block.sourceHandles.includes(s.handle))" :key="source.handle" class="ai-source" :disabled="!sourceAvailable(source)" :title="source.excerpt" @click="openSource(source)">{{source.title}}<small>{{!sourceAvailable(source)?'已移除':source.kind==='associated'?'关联资料，未读取全文':'查看依据'}}</small></button></div></section></template><template v-else-if="turn.result.kind==='search'"><button v-for="hit in turn.result.hits" :key="hit.pointId" class="result-item" :disabled="!points.some(p=>p.id===hit.pointId)" @click="emit('locate',hit.pointId)">{{points.find(p=>p.id===hit.pointId)?.name || '知识点已移除'}}</button></template></details></div><div v-if="output" class="ai-output" data-testid="ai-output"><p class="ai-output-question">{{lastQuestion}}</p><template v-if="output.kind==='search'"><p v-if="!hits.length" class="ai-help">没有找到可定位的已有知识。</p><button v-for="hit in hits" :key="hit.pointId" class="result-item" @click="emit('locate',hit.pointId)"><strong class="result-name">{{hit.point!.name}}</strong><span class="result-description">{{hit.reason}}</span><span class="ai-result-action">在图谱中查看</span></button></template><template v-else-if="output.kind==='answer'"><section v-for="(block,index) in output.blocks" :key="index" class="ai-answer-block"><p class="ai-basis">{{ {personal:'已有知识依据',inference:'结构推断',supplement:'AI 补充'}[block.basis] }}</p><MarkdownText :text="block.markdown" /><div class="ai-source-list"><button v-for="source in output.sources.filter(s=>block.sourceHandles.includes(s.handle))" :key="source.handle" class="ai-source" :disabled="!sourceAvailable(source)" :title="source.excerpt" @click="openSource(source)"><Icon :name="source.resourceId?'book':'layers'" :size="13" />{{source.title}}<small>{{!sourceAvailable(source)?'已移除':source.kind==='associated'?'关联资料，未读取全文':'查看依据'}}</small></button></div></section><button class="text-button" @click="action='answer'; question=''">继续追问</button></template><p v-if="output.note" class="ai-help">{{output.note}}</p></div></section></template>
<style scoped>.ai-knowledge-panel{padding:15px;min-width:0}.ai-mode-row{display:flex;gap:7px;align-items:center;margin-bottom:12px}.ai-new-session{margin-left:auto;white-space:nowrap}.ai-question{resize:vertical;min-height:88px;font-size:13px;line-height:1.7}.ai-context-summary{font-size:12px;line-height:1.7;color:#646464;margin:9px 0}.ai-submit-row{display:flex;justify-content:flex-end;gap:8px;margin-top:12px}.ai-check{display:flex;gap:8px;align-items:flex-start;font-size:12px;line-height:1.7;margin:10px 0}.ai-check input{flex-shrink:0;margin-top:2px}.ai-text-context{font-size:12px;color:#555;line-height:1.8;margin:10px 0}.ai-text-context summary{cursor:pointer}.ai-text-context label{display:flex;gap:8px;align-items:flex-start;padding:5px 0}.ai-output{padding-top:14px;margin-top:14px;border-top:1px solid #d1d1d1}.ai-output-question{font-size:13px;font-weight:600;line-height:1.7;margin-bottom:14px}.ai-answer-block{padding:13px 0;border-bottom:1px solid #ddd}.ai-basis{font-size:12px;color:#555;margin-bottom:9px}.ai-source-list{display:flex;flex-wrap:wrap;gap:7px;margin:10px 0}.ai-source{display:flex;gap:5px;align-items:center;text-align:left;padding:7px 8px;border:1px solid #ccc;border-radius:6px;background:#fff8;font-size:12px;overflow-wrap:anywhere}.ai-source small{font-size:11px;color:#646464}.ai-source:hover:not(:disabled){background:#fff}.ai-result-action{display:block;margin-top:6px;font-size:11px;color:#555}.result-description{display:block;font-size:13px;color:#646464;line-height:1.7;margin-top:7px}.ai-conversation-history{margin-top:15px;font-size:12px;line-height:1.7}.ai-conversation-history details{border-top:1px solid #ddd;padding:10px 0}.ai-conversation-history summary{cursor:pointer;overflow-wrap:anywhere}</style>
